<script setup lang="ts">
import { computed, nextTick, onBeforeUnmount, onMounted, reactive, ref } from 'vue'
import * as echarts from 'echarts'
import { ElMessage, ElMessageBox } from 'element-plus'
import { Connection, DataAnalysis, Key, Monitor, Plus, Refresh, Tickets, User, UserFilled, Setting, Collection, SwitchButton, DocumentCopy } from '@element-plus/icons-vue'
import { adminApi, authApi, portalApi, type Account, type AdminUsage, type ApiKey, type AuditLog, type Channel, type GatewaySettings, type ModelGroup, type NamedOption, type Overview, type Session, type Usage, type UsageFilters, type UserGroup } from './api'

type AdminPage = 'overview' | 'channels' | 'model-groups' | 'users' | 'user-groups' | 'usage' | 'logs' | 'gateway' | 'system'
type UserPage = 'marketplace' | 'keys' | 'usage' | 'settings'
const session = ref<Session | null>(null)
const workspace = ref<'admin' | 'user'>('user')
const adminPage = ref<AdminPage>('overview')
const userPage = ref<UserPage>('marketplace')
const loading = ref(false)
const loginForm = reactive({ username: '', password: '' })
const overviewRange = ref('today')
const overview = ref<Overview>({ gateway: { activeUsers: 0, streamingRequests: 0, concurrent: 0, maxConcurrent: 0, waiting: 0, queueCapacity: 0 }, userGroups: [], channels: [], usage: { tokens: 0, requests: 0, totalActiveUsers: 0 }, history: [] })
const gatewayChartEl = ref<HTMLElement>()
const timelineChartEl = ref<HTMLElement>()
let gatewayChart: echarts.ECharts | undefined
let timelineChart: echarts.ECharts | undefined
const channels = ref<Channel[]>([])
const users = ref<Account[]>([])
const modelGroups = ref<ModelGroup[]>([])
const availableGroupModels = ref<string[]>([])
const modelGroupDialog = ref(false)
const editingModelGroup = ref<ModelGroup | null>(null)
const modelGroupForm = reactive({ name: '', models: [] as string[], remark: '' })
const userGroups = ref<UserGroup[]>([])
const availableGroupMembers = ref<NamedOption[]>([])
const availableAuthorizedModelGroups = ref<NamedOption[]>([])
const userGroupDialog = ref(false)
const editingUserGroup = ref<UserGroup | null>(null)
const userGroupForm = reactive({ name: '', maxConcurrent: 0, apiKeyMaxConcurrent: 0, tokenQuota: 0, quotaPeriod: 'MONTH', memberTokenQuota: 0, memberMaxConcurrent: 0, remark: '', memberIds: [] as number[], modelGroupIds: [] as number[] })
const logs = ref<AuditLog[]>([])
const logTotal = ref(0)
const logDetailDrawer = ref(false)
const selectedLog = ref<AuditLog | null>(null)
const models = ref<string[]>([])
const userBaseUrl = ref('')
const keys = ref<ApiKey[]>([])
const usage = ref<Usage>({ requests: 0, errors: 0, inputTokens: 0, outputTokens: 0, totalTokens: 0, cacheTokens: 0, apiKeys: [], models: [], quotas: [] })
const userUsageFilter = reactive({ apiKey: '', model: '' })
const adminUsage = ref<AdminUsage>({ totals: { requests: 0, inputTokens: 0, outputTokens: 0, totalTokens: 0, cacheTokens: 0 }, providers: [], upstreamAccounts: [], modelGroups: [], models: [], userGroups: [], users: [] })
const usageFilters = ref<UsageFilters>({ users: [], providers: [], apiTypes: [] })
const usageFilterForm = reactive({ user: '', provider: '', apiType: '' })
const gatewaySettings = reactive<GatewaySettings>({ accessUrl: 'http://localhost:8080/v1', protocolConversionEnabled: true, maxConcurrent: 0, queueCapacity: 0, nonStreamTimeoutSeconds: 180, streamIdleTimeoutSeconds: 0, maxPayloadMb: 16 })
const adminPasswordForm = reactive({ currentPassword: '', newPassword: '', confirmPassword: '' })
const userPasswordForm = reactive({ currentPassword: '', newPassword: '', confirmPassword: '' })
const userDialog = ref(false)
const editingUser = ref<Account | null>(null)
const userForm = reactive({ username: '', password: '', confirmPassword: '', remark: '', status: 1 })
const keyDialog = ref(false)
const keyRemark = ref('')
const revealedKey = ref('')
const keyRevealDialog = ref(false)
const channelDialog = ref(false)
const testingDialog = ref(false)
const editingChannel = ref<Channel | null>(null)
const testingChannel = ref<Channel | null>(null)
const testModels = ref<string[]>([])
const testPrompt = ref('Reply with exactly: OK')
const testResults = ref<any[]>([])
const testing = ref(false)
const channelForm = reactive({ name: '', provider: 'custom', baseUrl: '', apiKey: '', protocol: 'openai-completions', supportedProtocols: ['openai-completions'] as string[], priority: 0, weight: 1, maxConcurrent: 0, defaultTestModel: '', status: 1, remark: '', models: [] as any[] })
const modelPickerDialog = ref(false)
const discoveringModels = ref(false)
const discoveredModels = ref<{ id: string; ownedBy?: string }[]>([])
const selectedDiscoveredModels = ref<string[]>([])

const title = computed(() => workspace.value === 'admin'
  ? ({ overview: '概览', channels: '账号池', 'model-groups': '模型组', users: '用户', 'user-groups': '用户组', usage: '用量统计', logs: '调用日志', gateway: '网关设置', system: '系统设置' }[adminPage.value])
  : ({ marketplace: '模型广场', keys: 'API Keys', usage: '用量统计', settings: '账户设置' }[userPage.value]))
const isAdmin = computed(() => session.value?.role === 'ADMIN')

function restoreSession() {
  const token = sessionStorage.getItem('ainexus.console.token')
  const username = sessionStorage.getItem('ainexus.console.username')
  const role = sessionStorage.getItem('ainexus.console.role') as Session['role'] | null
  if (token && username && role) { session.value = { token, username, role }; workspace.value = role === 'ADMIN' ? 'admin' : 'user'; loadCurrent() }
}
async function login() {
  try {
    loading.value = true
    const result = (await authApi.login(loginForm)).data
    session.value = result
    sessionStorage.setItem('ainexus.console.token', result.token)
    sessionStorage.setItem('ainexus.console.username', result.username)
    sessionStorage.setItem('ainexus.console.role', result.role)
    workspace.value = result.role === 'ADMIN' ? 'admin' : 'user'
    await loadCurrent()
  } catch (error: any) { ElMessage.error(error?.response?.data?.error?.message ?? '登录失败') } finally { loading.value = false }
}
function logout() { sessionStorage.clear(); session.value = null; loginForm.password = ''; }
async function copyText(value: string, label: string) { try { if (navigator.clipboard?.writeText && window.isSecureContext) { await navigator.clipboard.writeText(value) } else { const input = document.createElement('textarea'); input.value = value; input.setAttribute('readonly', ''); input.style.cssText = 'position:fixed;left:-9999px;top:0;opacity:0'; document.body.appendChild(input); input.select(); const copied = document.execCommand('copy'); document.body.removeChild(input); if (!copied) throw new Error('clipboard_copy_failed') } ElMessage.success(`${label} 已复制`) } catch { ElMessage.error(`复制失败，请手动复制${label}`) } }
async function copyModelId(model: string) { await copyText(model, '模型 ID') }
async function copyBaseUrl() { await copyText(userBaseUrl.value, 'Base URL') }
function renderOverviewCharts() {
  if (gatewayChartEl.value) { gatewayChart ??= echarts.init(gatewayChartEl.value); const limit = overview.value.gateway.maxConcurrent || Math.max(overview.value.gateway.concurrent, 1); const queueLimit = overview.value.gateway.queueCapacity || Math.max(overview.value.gateway.waiting, 1); gatewayChart.setOption({ grid: { left: 40, right: 20, top: 26, bottom: 28 }, xAxis: { type: 'category', data: ['网关并发', '等待队列'], axisTick: { show: false } }, yAxis: { type: 'value', max: Math.max(limit, queueLimit, 1), splitLine: { lineStyle: { color: '#e5e2d8' } } }, series: [{ type: 'bar', data: [{ value: overview.value.gateway.concurrent, itemStyle: { color: '#3b82f6' } }, { value: overview.value.gateway.waiting, itemStyle: { color: '#8b98aa' } }], barWidth: 34, label: { show: true, position: 'top', formatter: (item: any) => item.dataIndex === 0 ? `${item.value} / ${overview.value.gateway.maxConcurrent || '∞'}` : `${item.value} / ${overview.value.gateway.queueCapacity || '0'}` } }] }) }
  if (timelineChartEl.value) { timelineChart ??= echarts.init(timelineChartEl.value); const labels = overview.value.history.map(point => point.time.replace('T', ' ').slice(5, 16)); timelineChart.setOption({ tooltip: { trigger: 'axis' }, legend: { data: ['网关并发', '等待队列', '流式请求'], textStyle: { color: '#748078' } }, grid: { left: 42, right: 20, top: 38, bottom: 32 }, xAxis: { type: 'category', data: labels, boundaryGap: false, axisLabel: { color: '#748078' } }, yAxis: { type: 'value', minInterval: 1, splitLine: { lineStyle: { color: '#e5e2d8' } } }, series: [{ name: '网关并发', type: 'line', smooth: true, showSymbol: false, data: overview.value.history.map(point => point.concurrent), lineStyle: { color: '#3b82f6', width: 2 }, areaStyle: { color: 'rgba(59,130,246,.10)' } }, { name: '等待队列', type: 'line', smooth: true, showSymbol: false, data: overview.value.history.map(point => point.waiting), lineStyle: { color: '#8b98aa', width: 2 } }, { name: '流式请求', type: 'line', smooth: true, showSymbol: false, data: overview.value.history.map(point => point.streams), lineStyle: { color: '#5e8fdb', width: 2 } }] }) }
}
function changeOverviewRange(range: string) { overviewRange.value = range; loadCurrent() }
function switchWorkspace(next: 'admin' | 'user') { workspace.value = next; loadCurrent() }
async function loadCurrent() {
  if (!session.value) return
  try {
    loading.value = true
    if (workspace.value === 'admin') {
      if (adminPage.value === 'overview') { overview.value = (await adminApi.overview(overviewRange.value)).data; await nextTick(); renderOverviewCharts() }
      if (adminPage.value === 'channels') channels.value = (await adminApi.channels()).data
      if (adminPage.value === 'model-groups') { const [groups, available] = await Promise.all([adminApi.modelGroups(), adminApi.availableGroupModels()]); modelGroups.value = groups.data; availableGroupModels.value = available.data }
      if (adminPage.value === 'user-groups') { const [groups, members, modelGroups] = await Promise.all([adminApi.userGroups(), adminApi.availableGroupMembers(), adminApi.availableAuthorizedModelGroups()]); userGroups.value = groups.data; availableGroupMembers.value = members.data; availableAuthorizedModelGroups.value = modelGroups.data }
      if (adminPage.value === 'users') users.value = (await adminApi.users()).data
      if (adminPage.value === 'usage') { const [report, filters] = await Promise.all([adminApi.usage(usageFilterForm), adminApi.usageFilters()]); adminUsage.value = report.data; usageFilters.value = filters.data }
      if (adminPage.value === 'gateway') Object.assign(gatewaySettings, (await adminApi.gatewaySettings()).data)
      if (adminPage.value === 'logs') { const r = (await adminApi.logs({ page: 1, size: 50 })).data; logs.value = r.records; logTotal.value = r.total }
    } else {
      if (userPage.value === 'marketplace') { const catalog = (await portalApi.models()).data; models.value = catalog.models; userBaseUrl.value = catalog.baseUrl }
      if (userPage.value === 'keys') keys.value = (await portalApi.keys()).data
      if (userPage.value === 'usage') usage.value = (await portalApi.usage(userUsageFilter)).data
    }
  } catch (error: any) {
    if (error?.response?.status === 401) { ElMessage.error('登录会话已失效'); logout() }
    else ElMessage.error(error?.response?.data?.error?.message ?? '加载数据失败')
  } finally { loading.value = false }
}
function goAdmin(page: AdminPage) { adminPage.value = page; loadCurrent() }
function goUser(page: UserPage) { userPage.value = page; loadCurrent() }
function resetChannel() { editingChannel.value = null; Object.assign(channelForm, { name: '', provider: 'custom', baseUrl: '', apiKey: '', protocol: 'openai-completions', supportedProtocols: ['openai-completions'], priority: 0, weight: 1, maxConcurrent: 0, defaultTestModel: '', status: 1, remark: '', models: [] }) }
function openCreateChannel() { resetChannel(); channelDialog.value = true }
function openEditChannel(channel: Channel) { editingChannel.value = channel; Object.assign(channelForm, { ...channel, apiKey: '', supportedProtocols: channel.supportedProtocols?.length ? [...channel.supportedProtocols] : [channel.protocol], models: channel.models.map(model => ({ ...model })) }); channelDialog.value = true }
function ensureChannelProtocol() { if (!channelForm.supportedProtocols.length) channelForm.supportedProtocols = [channelForm.protocol]; if (!channelForm.supportedProtocols.includes(channelForm.protocol)) channelForm.protocol = channelForm.supportedProtocols[0] }
function changeChannelPrimaryProtocol() { if (!channelForm.supportedProtocols.includes(channelForm.protocol)) channelForm.supportedProtocols.push(channelForm.protocol) }
function addChannelModel() { channelForm.models.push({ modelName: '', upstreamModelName: '', status: 1, remark: '' }) }
function removeChannelModel(index: number) { channelForm.models.splice(index, 1) }
async function discoverUpstreamModels() {
  if (!channelForm.baseUrl) return ElMessage.warning('请先填写 Base URL')
  if (!editingChannel.value && !channelForm.apiKey) return ElMessage.warning('新增渠道时请先填写 API Key')
  try {
    discoveringModels.value = true
    const response = editingChannel.value && !channelForm.apiKey
      ? await adminApi.discoverSavedChannelModels(editingChannel.value.id)
      : await adminApi.discoverModels({ baseUrl: channelForm.baseUrl, apiKey: channelForm.apiKey, protocol: channelForm.protocol })
    discoveredModels.value = response.data
    const existing = new Set(channelForm.models.map(model => model.modelName))
    selectedDiscoveredModels.value = response.data.filter(model => !existing.has(model.id)).map(model => model.id)
    modelPickerDialog.value = true
  } catch (error: any) { ElMessage.error(error?.response?.data?.error?.message ?? '获取上游模型失败') } finally { discoveringModels.value = false }
}
function appendSelectedModels() {
  const existing = new Set(channelForm.models.map(model => model.modelName))
  let added = 0
  selectedDiscoveredModels.value.forEach((modelName) => { if (!existing.has(modelName)) { channelForm.models.push({ modelName, upstreamModelName: modelName, status: 1, remark: '' }); added++ } })
  modelPickerDialog.value = false
  ElMessage.success(`已添加 ${added} 个模型绑定`)
}
async function saveChannel() { if (!channelForm.name || !channelForm.baseUrl) return ElMessage.warning('请填写渠道名称和 Base URL'); try { const body = { ...channelForm, apiKey: channelForm.apiKey || undefined }; if (editingChannel.value) await adminApi.updateChannel(editingChannel.value.id, body); else await adminApi.createChannel(body); channelDialog.value = false; ElMessage.success('渠道已保存，路由缓存已刷新'); await loadCurrent() } catch (error: any) { ElMessage.error(error?.response?.data?.error?.message ?? '保存渠道失败') } }
async function toggleChannel(channel: Channel) { await adminApi.channelStatus(channel.id, channel.status ? 0 : 1); ElMessage.success('渠道状态已更新'); loadCurrent() }
async function removeChannel(channel: Channel) { await ElMessageBox.confirm(`删除渠道 ${channel.name} 及其模型绑定？`, '确认删除', { type: 'warning' }); await adminApi.deleteChannel(channel.id); ElMessage.success('渠道已删除'); loadCurrent() }
function openChannelTest(channel: Channel) { testingChannel.value = channel; testModels.value = channel.defaultTestModel && channel.models.some(model => model.modelName === channel.defaultTestModel) ? [channel.defaultTestModel] : channel.models.slice(0, 1).map(model => model.modelName); testPrompt.value = 'Reply with exactly: OK'; testResults.value = []; testingDialog.value = true }
async function runChannelTest() { if (!testingChannel.value || !testModels.value.length) return ElMessage.warning('请至少选择一个模型'); try { testing.value = true; testResults.value = (await adminApi.testChannel(testingChannel.value.id, { modelNames: testModels.value, prompt: testPrompt.value })).data; const failures = testResults.value.filter(result => !result.success).length; failures ? ElMessage.warning(`完成：${testResults.value.length - failures} 可用，${failures} 失败`) : ElMessage.success('所选模型均可用') } catch (error: any) { ElMessage.error(error?.response?.data?.error?.message ?? '测试失败') } finally { testing.value = false } }
async function saveGatewaySettings() { try { Object.assign(gatewaySettings, (await adminApi.updateGatewaySettings(gatewaySettings)).data); ElMessage.success('网关设置已保存并即时生效') } catch (error: any) { ElMessage.error(error?.response?.data?.error?.message ?? '保存网关设置失败') } }
async function changeAdminPassword() { if (!adminPasswordForm.currentPassword || !adminPasswordForm.newPassword || !adminPasswordForm.confirmPassword) return ElMessage.warning('请填写所有密码字段'); if (adminPasswordForm.newPassword !== adminPasswordForm.confirmPassword) return ElMessage.warning('两次输入的新密码不一致'); try { await adminApi.changeAdminPassword(adminPasswordForm); ElMessage.success('密码已修改，请使用新密码重新登录'); Object.assign(adminPasswordForm, { currentPassword: '', newPassword: '', confirmPassword: '' }); logout() } catch (error: any) { ElMessage.error(error?.response?.data?.error?.message ?? '修改密码失败') } }
async function changeUserPassword() { if (!userPasswordForm.currentPassword || !userPasswordForm.newPassword || !userPasswordForm.confirmPassword) return ElMessage.warning('请填写所有密码字段'); if (userPasswordForm.newPassword !== userPasswordForm.confirmPassword) return ElMessage.warning('两次输入的新密码不一致'); try { await portalApi.changePassword(userPasswordForm); ElMessage.success('密码已修改，请使用新密码重新登录'); Object.assign(userPasswordForm, { currentPassword: '', newPassword: '', confirmPassword: '' }); logout() } catch (error: any) { ElMessage.error(error?.response?.data?.error?.message ?? '修改密码失败') } }
async function openLogDetail(log: AuditLog) { try { selectedLog.value = (await adminApi.logDetail(log.id)).data; logDetailDrawer.value = true } catch (error: any) { ElMessage.error(error?.response?.data?.error?.message ?? '加载调用详情失败') } }
function detailValue(value: unknown) { return value === null || value === undefined || value === '' ? '未采集' : String(value) }
function openCreateUserGroup() { editingUserGroup.value = null; Object.assign(userGroupForm, { name: '', maxConcurrent: 0, apiKeyMaxConcurrent: 0, tokenQuota: 0, quotaPeriod: 'MONTH', memberTokenQuota: 0, memberMaxConcurrent: 0, remark: '', memberIds: [], modelGroupIds: [] }); userGroupDialog.value = true }
function openEditUserGroup(group: UserGroup) { editingUserGroup.value = group; Object.assign(userGroupForm, { name: group.name, maxConcurrent: group.maxConcurrent, apiKeyMaxConcurrent: group.apiKeyMaxConcurrent, tokenQuota: group.tokenQuota, quotaPeriod: group.quotaPeriod, memberTokenQuota: group.memberTokenQuota, memberMaxConcurrent: group.memberMaxConcurrent, remark: group.remark ?? '', memberIds: [...group.memberIds], modelGroupIds: [...group.modelGroupIds] }); userGroupDialog.value = true }
async function saveUserGroup() { if (!userGroupForm.name) return ElMessage.warning('请填写用户组名称'); try { if (editingUserGroup.value) await adminApi.updateUserGroup(editingUserGroup.value.id, userGroupForm); else await adminApi.createUserGroup(userGroupForm); userGroupDialog.value = false; ElMessage.success('用户组已保存'); await loadCurrent() } catch (error: any) { ElMessage.error(error?.response?.data?.error?.message ?? '保存用户组失败') } }
async function removeUserGroup(group: UserGroup) { await ElMessageBox.confirm(`删除用户组 ${group.name}？`, '确认删除', { type: 'warning' }); await adminApi.deleteUserGroup(group.id); ElMessage.success('用户组已删除'); loadCurrent() }
function quotaDisplay(value: number) { return value === 0 ? '不限制' : value.toLocaleString() }
function openCreateModelGroup() { editingModelGroup.value = null; Object.assign(modelGroupForm, { name: '', models: [], remark: '' }); modelGroupDialog.value = true }
function openEditModelGroup(group: ModelGroup) { editingModelGroup.value = group; Object.assign(modelGroupForm, { name: group.name, models: [...group.models], remark: group.remark ?? '' }); modelGroupDialog.value = true }
async function saveModelGroup() { if (!modelGroupForm.name || !modelGroupForm.models.length) return ElMessage.warning('请填写名称并至少选择一个模型'); try { if (editingModelGroup.value) await adminApi.updateModelGroup(editingModelGroup.value.id, modelGroupForm); else await adminApi.createModelGroup(modelGroupForm); modelGroupDialog.value = false; ElMessage.success('模型组已保存'); await loadCurrent() } catch (error: any) { ElMessage.error(error?.response?.data?.error?.message ?? '保存模型组失败') } }
async function removeModelGroup(group: ModelGroup) { await ElMessageBox.confirm(`删除模型组 ${group.name}？`, '确认删除', { type: 'warning' }); await adminApi.deleteModelGroup(group.id); ElMessage.success('模型组已删除'); loadCurrent() }
function openCreateUser() { editingUser.value = null; Object.assign(userForm, { username: '', password: '', confirmPassword: '', remark: '', status: 1 }); userDialog.value = true }
function openEditUser(item: Account) { editingUser.value = item; Object.assign(userForm, { username: item.username, password: '', confirmPassword: '', remark: item.remark ?? '', status: item.status }); userDialog.value = true }
async function saveUser() {
  if (!editingUser.value && (!userForm.username || !userForm.password || !userForm.confirmPassword)) return ElMessage.warning('请填写用户名、密码和确认密码')
  if (userForm.password || userForm.confirmPassword) { if (userForm.password !== userForm.confirmPassword) return ElMessage.warning('两次输入的密码不一致') }
  try {
    if (editingUser.value) await adminApi.updateUser(editingUser.value.id, { password: userForm.password || undefined, confirmPassword: userForm.confirmPassword || undefined, remark: userForm.remark, status: userForm.status })
    else await adminApi.createUser(userForm)
    userDialog.value = false; ElMessage.success('用户已保存'); await loadCurrent()
  } catch (error: any) { ElMessage.error(error?.response?.data?.error?.message ?? '保存失败') }
}
async function removeUser(item: Account) { await ElMessageBox.confirm(`删除用户 ${item.username}？`, '确认删除', { type: 'warning' }); await adminApi.deleteUser(item.id); ElMessage.success('用户已删除'); loadCurrent() }
async function createKey() { try { const r = (await portalApi.createKey({ remark: keyRemark.value || undefined })).data; revealedKey.value = r.token; keyDialog.value = false; keyRevealDialog.value = true; keyRemark.value = ''; await loadCurrent() } catch { ElMessage.error('创建 API Key 失败') } }
async function removeKey(item: ApiKey) { await ElMessageBox.confirm('撤销该 API Key？', '确认撤销', { type: 'warning' }); await portalApi.deleteKey(item.id); ElMessage.success('API Key 已撤销'); loadCurrent() }
function copyKey() { copyText(revealedKey.value, 'API Key') }

onMounted(restoreSession)
onBeforeUnmount(() => { gatewayChart?.dispose(); timelineChart?.dispose() })
</script>

<template>
  <main v-if="!session" class="login-shell">
    <section class="login-panel"><p class="eyebrow">AINEXUS / PRIVATE GATEWAY</p><h1>Control<br>Access.</h1><p class="login-copy">统一管理模型网关、访问凭据与内部调用。</p><el-form label-position="top" @submit.prevent="login"><el-form-item label="用户名"><el-input v-model="loginForm.username" autocomplete="username" /></el-form-item><el-form-item label="密码"><el-input v-model="loginForm.password" type="password" show-password autocomplete="current-password" @keyup.enter="login" /></el-form-item><el-button type="primary" class="login-button" :loading="loading" @click="login">登录控制台</el-button></el-form></section><aside class="login-aside"><span class="login-mark">A</span><div><p>AI NEXUS</p><b>INTERNAL<br>OPERATIONS</b></div></aside>
  </main>

  <main v-else class="shell">
    <aside class="rail"><div class="brand"><span class="brand-mark">A</span><div><b>AiNexus</b><small>{{ workspace === 'admin' ? 'ADMIN CONTROL' : 'USER PORTAL' }}</small></div></div>
      <nav v-if="workspace === 'admin'" class="nav-list"><button :class="{active:adminPage==='overview'}" @click="goAdmin('overview')"><DataAnalysis />概览</button><button :class="{active:adminPage==='channels'}" @click="goAdmin('channels')"><Connection />账号池</button><button :class="{active:adminPage==='model-groups'}" @click="goAdmin('model-groups')"><Collection />模型组</button><button :class="{active:adminPage==='users'}" @click="goAdmin('users')"><User />用户</button><button :class="{active:adminPage==='user-groups'}" @click="goAdmin('user-groups')"><UserFilled />用户组</button><button :class="{active:adminPage==='usage'}" @click="goAdmin('usage')"><Monitor />用量统计</button><button :class="{active:adminPage==='logs'}" @click="goAdmin('logs')"><Tickets />调用日志</button><button :class="{active:adminPage==='gateway'}" @click="goAdmin('gateway')"><Connection />网关设置</button><button :class="{active:adminPage==='system'}" @click="goAdmin('system')"><Setting />系统设置</button></nav>
      <nav v-else class="nav-list"><button :class="{active:userPage==='marketplace'}" @click="goUser('marketplace')"><Collection />模型广场</button><button :class="{active:userPage==='keys'}" @click="goUser('keys')"><Key />API Keys</button><button :class="{active:userPage==='usage'}" @click="goUser('usage')"><Monitor />用量统计</button><button :class="{active:userPage==='settings'}" @click="goUser('settings')"><Setting />账户设置</button></nav>
      <div class="rail-footer"><span class="live-dot"></span>{{ session.username }} · {{ session.role }}</div></aside>
    <section class="workspace" v-loading="loading"><header class="topbar"><div><p class="eyebrow">{{ workspace === 'admin' ? 'ADMIN CONSOLE' : 'USER WORKSPACE' }}</p><h1>{{ title }}</h1></div><div class="workspace-actions"><el-button v-if="isAdmin" :type="workspace==='admin'?'primary':'default'" @click="switchWorkspace(workspace==='admin'?'user':'admin')"><SwitchButton />{{ workspace==='admin'?'切换用户端':'切换管理端' }}</el-button><el-button @click="logout">退出登录</el-button></div></header>

      <section v-if="workspace==='admin' && adminPage==='overview'" class="overview-page"><div class="panel-head"><div><p class="eyebrow">LIVE GATEWAY OPERATIONS</p><h2>网关状态</h2></div><el-button :icon="Refresh" @click="loadCurrent">刷新</el-button></div><div class="overview-status-grid"><section class="overview-live"><div class="live-heading"><div><p class="eyebrow">LIVE CAPACITY</p><h3>当前网关负载</h3></div><span class="live-dot"></span></div><div class="live-counters"><article><span>活跃用户</span><b>{{overview.gateway.activeUsers}}</b></article><article><span>流式请求</span><b>{{overview.gateway.streamingRequests}}</b></article><article><span>网关并发</span><b>{{overview.gateway.concurrent}} / {{overview.gateway.maxConcurrent || '∞'}}</b></article><article><span>等待队列</span><b>{{overview.gateway.waiting}} / {{overview.gateway.queueCapacity}}</b></article></div><div ref="gatewayChartEl" class="overview-chart capacity-chart"></div></section><section class="overview-usage"><div class="range-tabs"><h3>用量统计</h3><el-radio-group :model-value="overviewRange" size="small" @change="changeOverviewRange"><el-radio-button value="today">今日</el-radio-button><el-radio-button value="24h">近24小时</el-radio-button><el-radio-button value="7d">近7天</el-radio-button><el-radio-button value="30d">近30天</el-radio-button></el-radio-group></div><div class="usage-kpis"><article><span>Token</span><b>{{overview.usage.tokens.toLocaleString()}}</b></article><article><span>请求统计</span><b>{{overview.usage.requests.toLocaleString()}}</b></article><article><span>总活跃用户</span><b>{{overview.usage.totalActiveUsers.toLocaleString()}}</b></article></div></section></div><div class="overview-tables"><section><div class="section-title"><div><p class="eyebrow">USER GROUP CONCURRENCY</p><h3>用户组并发</h3></div></div><el-table :data="overview.userGroups" size="small" max-height="260"><el-table-column prop="name" label="用户组" min-width="150"/><el-table-column label="当前 / 上限" width="130"><template #default="{row}">{{row.active}} / {{row.limit || '∞'}}</template></el-table-column><el-table-column label="利用率" width="145"><template #default="{row}"><el-progress :percentage="row.limit ? Math.min(100,Math.round(row.active/row.limit*100)) : 0" :format="row.limit ? undefined : ()=>'不限制'" :stroke-width="9"/></template></el-table-column></el-table></section><section><div class="section-title"><div><p class="eyebrow">UPSTREAM ACCOUNT CONCURRENCY</p><h3>模型账号并发</h3></div></div><el-table :data="overview.channels" size="small" max-height="260"><el-table-column prop="name" label="上游账号" min-width="145"><template #default="{row}"><b>{{row.name}}</b><small class="sub">{{row.provider}}</small></template></el-table-column><el-table-column prop="priority" label="优先级" width="80"/><el-table-column label="当前 / 上限" width="115"><template #default="{row}">{{row.active}} / {{row.limit || '∞'}}</template></el-table-column><el-table-column label="利用率" width="120"><template #default="{row}"><el-progress :percentage="row.limit ? Math.min(100,Math.round(row.active/row.limit*100)) : 0" :format="row.limit ? undefined : ()=>'不限制'" :stroke-width="8"/></template></el-table-column><el-table-column label="健康状态" width="110"><template #default="{row}"><el-tag :type="row.health==='HEALTHY'?'success':'danger'">{{row.health==='HEALTHY'?'健康':'熔断'}}</el-tag></template></el-table-column></el-table></section></div><section class="timeline-panel"><div class="range-tabs"><div><p class="eyebrow">CONCURRENCY HISTORY</p><h3>历史并发</h3></div><el-radio-group :model-value="overviewRange" size="small" @change="changeOverviewRange"><el-radio-button value="today">今日</el-radio-button><el-radio-button value="24h">近24小时</el-radio-button><el-radio-button value="7d">近7天</el-radio-button><el-radio-button value="30d">近30天</el-radio-button></el-radio-group></div><div ref="timelineChartEl" class="overview-chart timeline-chart"></div></section></section>
      <section v-else-if="workspace==='admin' && adminPage==='channels'" class="page-panel"><div class="panel-head"><div><p class="eyebrow">UPSTREAM ACCOUNT POOL</p><h2>账号池</h2></div><div class="workspace-actions"><el-button :icon="Refresh" @click="loadCurrent">刷新</el-button><el-button type="primary" :icon="Plus" @click="openCreateChannel">新增渠道</el-button></div></div><el-table :data="channels" class="dense-table"><el-table-column prop="name" label="渠道" min-width="160"><template #default="{row}"><b>{{row.name}}</b><small class="sub">{{row.provider}} · {{row.baseUrl}}</small></template></el-table-column><el-table-column label="协议" min-width="200"><template #default="{row}"><el-tag v-for="p in row.supportedProtocols ?? [row.protocol]" :key="p" class="protocol-tag" :type="p===row.protocol?'success':'info'">{{p}}</el-tag></template></el-table-column><el-table-column label="模型绑定" width="120"><template #default="{row}"><el-tag effect="plain">已绑定 {{row.models.length}} 个</el-tag></template></el-table-column><el-table-column label="状态" width="90"><template #default="{row}"><el-tag :type="row.status?'success':'info'">{{row.status?'启用':'停用'}}</el-tag></template></el-table-column><el-table-column label="操作" width="265" fixed="right"><template #default="{row}"><el-button link type="primary" @click="openChannelTest(row)">测试</el-button><el-button link type="primary" @click="openEditChannel(row)">编辑</el-button><el-button link @click="toggleChannel(row)">{{row.status?'停用':'启用'}}</el-button><el-button link type="danger" @click="removeChannel(row)">删除</el-button></template></el-table-column></el-table></section>
      <section v-else-if="workspace==='admin' && adminPage==='model-groups'" class="page-panel"><div class="panel-head"><div><p class="eyebrow">MODEL COLLECTIONS</p><h2>模型组</h2></div><div class="workspace-actions"><el-button :icon="Refresh" @click="loadCurrent">刷新</el-button><el-button type="primary" :icon="Plus" @click="openCreateModelGroup">新增模型组</el-button></div></div><el-table :data="modelGroups" class="dense-table"><el-table-column prop="name" label="名称" min-width="180"/><el-table-column label="模型" min-width="280"><template #default="{row}"><el-tag v-for="model in row.models.slice(0,4)" :key="model" class="protocol-tag" effect="plain">{{model}}</el-tag><small v-if="row.models.length>4" class="sub">另 {{row.models.length-4}} 个</small></template></el-table-column><el-table-column label="数量" width="90"><template #default="{row}">{{row.models.length}}</template></el-table-column><el-table-column prop="remark" label="备注" min-width="180" show-overflow-tooltip/><el-table-column prop="updateTime" label="更新时间" width="180"/><el-table-column label="操作" width="150"><template #default="{row}"><el-button link type="primary" @click="openEditModelGroup(row)">编辑</el-button><el-button link type="danger" @click="removeModelGroup(row)">删除</el-button></template></el-table-column></el-table></section>
      <section v-else-if="workspace==='admin' && adminPage==='user-groups'" class="page-panel"><div class="panel-head"><div><p class="eyebrow">ACCESS POLICY & QUOTA</p><h2>用户组</h2></div><div class="workspace-actions"><el-button :icon="Refresh" @click="loadCurrent">刷新</el-button><el-button type="primary" :icon="Plus" @click="openCreateUserGroup">新增用户组</el-button></div></div><el-table :data="userGroups" class="dense-table"><el-table-column prop="name" label="名称" min-width="150"/><el-table-column label="成员" width="110"><template #default="{row}"><el-tag effect="plain">{{row.memberNames.length}} 人</el-tag></template></el-table-column><el-table-column label="授权模型组" min-width="180"><template #default="{row}"><el-tag v-for="name in row.modelGroupNames.slice(0,2)" :key="name" class="protocol-tag" effect="plain">{{name}}</el-tag><small v-if="row.modelGroupNames.length>2" class="sub">另 {{row.modelGroupNames.length-2}} 个</small></template></el-table-column><el-table-column label="组并发 / Key 并发" width="155"><template #default="{row}">{{quotaDisplay(row.maxConcurrent)}} / {{quotaDisplay(row.apiKeyMaxConcurrent)}}</template></el-table-column><el-table-column label="组剩余 Token / 配额" width="190"><template #default="{row}"><b>{{row.remainingTokenQuota === null || row.remainingTokenQuota === undefined ? '不限制' : quotaDisplay(row.remainingTokenQuota)}} / {{quotaDisplay(row.tokenQuota)}}</b><small v-if="row.tokenQuota" class="sub">已用 {{quotaDisplay(row.usedPromptTokens)}} · {{row.quotaPeriod}}</small></template></el-table-column><el-table-column label="成员 Token / 并发" width="160"><template #default="{row}">{{quotaDisplay(row.memberTokenQuota)}} / {{quotaDisplay(row.memberMaxConcurrent)}}</template></el-table-column><el-table-column prop="remark" label="备注" min-width="160" show-overflow-tooltip/><el-table-column label="操作" width="150"><template #default="{row}"><el-button link type="primary" @click="openEditUserGroup(row)">编辑</el-button><el-button link type="danger" @click="removeUserGroup(row)">删除</el-button></template></el-table-column></el-table></section>
      <section v-else-if="workspace==='admin' && adminPage==='usage'" class="page-panel usage-page"><div class="panel-head"><div><p class="eyebrow">USAGE ANALYTICS</p><h2>用量统计</h2></div><el-button :icon="Refresh" @click="loadCurrent">刷新</el-button></div><div class="usage-filter"><el-select v-model="usageFilterForm.user" clearable filterable placeholder="全部用户" @change="loadCurrent"><el-option v-for="item in usageFilters.users" :key="item" :label="item" :value="item"/></el-select><el-select v-model="usageFilterForm.provider" clearable filterable placeholder="全部供应商" @change="loadCurrent"><el-option v-for="item in usageFilters.providers" :key="item" :label="item" :value="item"/></el-select><el-select v-model="usageFilterForm.apiType" clearable placeholder="全部 API 类型" @change="loadCurrent"><el-option v-for="item in usageFilters.apiTypes" :key="item" :label="item" :value="item"/></el-select><el-button @click="Object.assign(usageFilterForm,{user:'',provider:'',apiType:''});loadCurrent()">重置筛选</el-button></div><div class="metrics usage-metrics"><article><span>请求量</span><strong>{{adminUsage.totals.requests.toLocaleString()}}</strong></article><article><span>输入 Token</span><strong>{{adminUsage.totals.inputTokens.toLocaleString()}}</strong></article><article><span>输出 Token</span><strong>{{adminUsage.totals.outputTokens.toLocaleString()}}</strong></article><article><span>总 Token</span><strong>{{adminUsage.totals.totalTokens.toLocaleString()}}</strong></article><article><span>缓存 Token</span><strong>{{adminUsage.totals.cacheTokens.toLocaleString()}}</strong></article></div><div class="usage-distributions"><section v-for="section in [{title:'按供应商分布',data:adminUsage.providers},{title:'按上游账号分布',data:adminUsage.upstreamAccounts},{title:'按模型组分布',data:adminUsage.modelGroups},{title:'按模型分布',data:adminUsage.models},{title:'按用户组分布',data:adminUsage.userGroups},{title:'按用户分布',data:adminUsage.users}]" :key="section.title" class="usage-table"><h3>{{section.title}}</h3><el-table :data="section.data" size="small" max-height="260"><el-table-column prop="name" label="名称" min-width="160" show-overflow-tooltip/><el-table-column prop="requests" label="请求量" width="90"/><el-table-column prop="totalTokens" label="总 Token" width="115"/><el-table-column prop="cacheTokens" label="缓存 Token" width="115"/></el-table></section></div></section>
      <section v-else-if="workspace==='admin' && adminPage==='users'" class="page-panel"><div class="panel-head"><div><p class="eyebrow">IDENTITY DIRECTORY</p><h2>用户</h2></div><el-button type="primary" :icon="Plus" @click="openCreateUser">新增用户</el-button></div><el-table :data="users" class="dense-table"><el-table-column prop="username" label="用户名" min-width="200" /><el-table-column prop="remark" label="备注" min-width="220" show-overflow-tooltip /><el-table-column label="状态" width="100"><template #default="{row}"><el-tag :type="row.status?'success':'info'">{{row.status?'启用':'停用'}}</el-tag></template></el-table-column><el-table-column prop="createTime" label="创建时间" width="180" /><el-table-column label="操作" width="150"><template #default="{row}"><el-button link type="primary" @click="openEditUser(row)">编辑</el-button><el-button link type="danger" @click="removeUser(row)">删除</el-button></template></el-table-column></el-table></section>
      <section v-else-if="workspace==='admin' && adminPage==='gateway'" class="page-panel gateway-settings"><div class="panel-head"><div><p class="eyebrow">GATEWAY RUNTIME CONTROLS</p><h2>网关设置</h2></div><div class="workspace-actions"><el-button :icon="Refresh" @click="loadCurrent">刷新</el-button><el-button type="primary" @click="saveGatewaySettings">保存设置</el-button></div></div><section class="settings-section"><h3>基础设置</h3><el-form label-position="top"><el-form-item label="接入地址"><el-input v-model="gatewaySettings.accessUrl" placeholder="http://localhost:8080/v1"/><small>用户通过此 OpenAI Base URL 接入网关，支持 HTTP 和 HTTPS，地址需以 /v1 结尾。</small></el-form-item><el-form-item label="协议转换"><el-switch v-model="gatewaySettings.protocolConversionEnabled" active-text="开启" inactive-text="关闭"/><small>开启后，可在无可用原生账号时使用已支持的 Chat Completions、Responses 与 Anthropic Messages 直接转换，原生协议始终优先。</small></el-form-item></el-form></section><section class="settings-section"><h3>性能设置</h3><el-form label-position="top" class="gateway-performance-form"><el-form-item label="最大并发"><el-input-number v-model="gatewaySettings.maxConcurrent" :min="0"/><small>网关同时处理的最大请求数，0 表示不限制；超出部分进入等待队列。</small></el-form-item><el-form-item label="等待队列大小"><el-input-number v-model="gatewaySettings.queueCapacity" :min="0"/><small>并发占满时允许排队等待的最大请求数，为 0 或队列已满时新请求直接失败。</small></el-form-item><el-form-item label="非流式请求超时（秒）"><el-input-number v-model="gatewaySettings.nonStreamTimeoutSeconds" :min="1"/><small>上游非流式响应的读取和总调用超时。</small></el-form-item><el-form-item label="流式空闲超时（秒）"><el-input-number v-model="gatewaySettings.streamIdleTimeoutSeconds" :min="0"/><small>两段流式响应数据之间的最大等待时间，0 表示不限制。</small></el-form-item><el-form-item label="最大报文大小（MB）"><el-input-number v-model="gatewaySettings.maxPayloadMb" :min="1" :max="1024"/><small>超出限制的请求会在网关入口拒绝。</small></el-form-item></el-form></section></section>
      <section v-else-if="workspace==='admin' && adminPage==='system'" class="page-panel system-settings"><div class="panel-head"><div><p class="eyebrow">ADMINISTRATION SECURITY</p><h2>系统设置</h2></div></div><section class="settings-section password-settings"><div><h3>管理员账号密码</h3><p>修改后当前控制台会话将退出，需要使用新密码重新登录。</p></div><el-form label-position="top" @submit.prevent="changeAdminPassword"><el-form-item label="当前密码"><el-input v-model="adminPasswordForm.currentPassword" type="password" show-password autocomplete="current-password"/></el-form-item><el-form-item label="新密码"><el-input v-model="adminPasswordForm.newPassword" type="password" show-password autocomplete="new-password"/><small>密码长度为 8 至 128 个字符。</small></el-form-item><el-form-item label="确认新密码"><el-input v-model="adminPasswordForm.confirmPassword" type="password" show-password autocomplete="new-password" @keyup.enter="changeAdminPassword"/></el-form-item><el-button type="primary" @click="changeAdminPassword">更新管理员密码</el-button></el-form></section></section>
      <section v-else-if="workspace==='admin' && adminPage==='logs'" class="page-panel"><div class="panel-head"><div><p class="eyebrow">REQUEST TRACE</p><h2>调用日志</h2></div><el-button :icon="Refresh" @click="loadCurrent">刷新</el-button></div><el-table :data="logs" class="dense-table" max-height="calc(100vh - 260px)"><el-table-column prop="requestId" label="Request ID" width="185" show-overflow-tooltip/><el-table-column label="供应商 / 账号" min-width="155"><template #default="{row}"><b>{{detailValue(row.provider)}}</b><small class="sub">{{detailValue(row.upstreamAccount)}}</small></template></el-table-column><el-table-column label="请求 / 上游模型" min-width="175"><template #default="{row}"><b>{{detailValue(row.requestModel)}}</b><small class="sub">{{detailValue(row.upstreamModel)}}</small></template></el-table-column><el-table-column label="用户 / 用户组" min-width="150"><template #default="{row}"><b>{{detailValue(row.userName)}}</b><small class="sub">{{detailValue(row.userGroupNames)}}</small></template></el-table-column><el-table-column prop="inputTokens" label="输入" width="80"/><el-table-column prop="outputTokens" label="输出" width="80"/><el-table-column prop="totalTokens" label="总 Token" width="95"/><el-table-column prop="cacheTokens" label="缓存" width="80"/><el-table-column prop="statusCode" label="状态" width="80"><template #default="{row}"><el-tag :type="row.statusCode<400?'success':'danger'">{{row.statusCode}}</el-tag></template></el-table-column><el-table-column prop="createTime" label="调用时间" width="175"/><el-table-column label="操作" width="80" fixed="right"><template #default="{row}"><el-button link type="primary" @click="openLogDetail(row)">查看</el-button></template></el-table-column></el-table></section>
      <section v-else-if="workspace==='admin'" class="empty-module"><p class="eyebrow">CONFIGURATION MODULE</p><h2>{{ title }}</h2><p>该模块已纳入控制台导航。模型组、用户组和配置项将在下一步接入可持久化的策略与分配规则。</p></section>

      <section v-else-if="userPage==='marketplace'" class="user-page user-marketplace"><div class="user-page-head"><div><p class="eyebrow">MODEL CATALOG</p><h2>模型广场</h2><p>选择已授权的模型 ID，用于 OpenAI 兼容接口调用。</p></div><el-button :icon="Refresh" circle plain aria-label="刷新模型目录" @click="loadCurrent"/></div><section class="connection-block"><div><span class="connection-label">OPENAI BASE URL</span><div class="base-url-value"><code>{{userBaseUrl}}</code><el-tooltip content="复制 Base URL" placement="top"><el-button :icon="DocumentCopy" circle plain aria-label="复制 Base URL" @click="copyBaseUrl"/></el-tooltip></div></div><span class="connection-state"><i></i>可用</span></section><section class="catalog-block"><div class="catalog-title"><div><h3>已授权模型</h3><span>{{models.length}} 个模型</span></div><small>点击图标复制模型 ID</small></div><div class="model-grid user-model-grid"><article v-for="model in models" :key="model"><span class="model-symbol"><Collection /></span><div class="model-id-row"><b>{{model}}</b><small>MODEL ID</small></div><el-tooltip content="复制模型 ID" placement="top"><el-button :icon="DocumentCopy" circle plain aria-label="复制模型 ID" @click="copyModelId(model)"/></el-tooltip></article><p v-if="!models.length" class="empty-note">当前没有可用模型。</p></div></section></section>
      <section v-else-if="userPage==='keys'" class="user-page user-keys"><div class="user-page-head"><div><p class="eyebrow">PERSONAL CREDENTIALS</p><h2>API Keys</h2><p>管理连接 AiNexus 网关的个人访问凭据。</p></div><el-button type="primary" :icon="Plus" @click="keyDialog=true">创建 API Key</el-button></div><section class="credential-block"><div class="credential-summary"><span class="summary-icon"><Key /></span><div><b>{{keys.length}}</b><span>个已创建的 API Key</span></div></div><div class="credential-list"><article v-for="row in keys" :key="row.id" class="credential-item"><div class="credential-main"><span class="credential-status" :class="{disabled:row.status!==1}"></span><div><code>{{row.tokenMasked}}</code><p>{{row.remark || '未添加备注'}}</p></div></div><div class="credential-meta"><span>{{row.createTime || '未知创建时间'}}</span><el-button link type="danger" @click="removeKey(row)">撤销</el-button></div></article><p v-if="!keys.length" class="empty-note">尚未创建 API Key。</p></div></section></section>
      <section v-else-if="userPage==='settings'" class="user-page user-settings"><div class="user-page-head"><div><p class="eyebrow">ACCOUNT SECURITY</p><h2>账户设置</h2><p>更新账户密码后，需要使用新密码重新登录。</p></div></div><section class="user-password-block"><div class="user-password-intro"><span class="summary-icon"><Setting /></span><div><h3>修改登录密码</h3><p>新密码长度必须为 8 至 128 个字符。</p></div></div><el-form label-position="top" @submit.prevent="changeUserPassword"><el-form-item label="当前密码"><el-input v-model="userPasswordForm.currentPassword" type="password" show-password autocomplete="current-password"/></el-form-item><el-form-item label="新密码"><el-input v-model="userPasswordForm.newPassword" type="password" show-password autocomplete="new-password"/></el-form-item><el-form-item label="确认新密码"><el-input v-model="userPasswordForm.confirmPassword" type="password" show-password autocomplete="new-password" @keyup.enter="changeUserPassword"/></el-form-item><el-button type="primary" @click="changeUserPassword">更新密码</el-button></el-form></section></section>
      <section v-else class="user-page user-usage"><div class="user-page-head"><div><p class="eyebrow">PERSONAL API CONSUMPTION</p><h2>用量统计</h2><p>按凭据和模型查看当前账户的调用消耗与可用额度。</p></div><el-button :icon="Refresh" circle plain aria-label="刷新用量" @click="loadCurrent"/></div><section class="usage-filter-block"><span>筛选范围</span><el-select v-model="userUsageFilter.apiKey" clearable filterable placeholder="全部 API Key" @change="loadCurrent"><el-option v-for="item in usage.apiKeys" :key="item" :label="item" :value="item"/></el-select><el-select v-model="userUsageFilter.model" clearable filterable placeholder="全部模型" @change="loadCurrent"><el-option v-for="item in usage.models" :key="item" :label="item" :value="item"/></el-select><el-button plain @click="Object.assign(userUsageFilter,{apiKey:'',model:''});loadCurrent()">重置</el-button></section><div class="usage-stat-grid"><article><span>请求量</span><strong>{{usage.requests.toLocaleString()}}</strong></article><article class="tone-brown"><span>异常调用</span><strong>{{usage.errors.toLocaleString()}}</strong></article><article><span>输入 Token</span><strong>{{usage.inputTokens.toLocaleString()}}</strong></article><article><span>输出 Token</span><strong>{{usage.outputTokens.toLocaleString()}}</strong></article><article class="tone-green"><span>总 Token</span><strong>{{usage.totalTokens.toLocaleString()}}</strong></article><article><span>缓存 Token</span><strong>{{usage.cacheTokens.toLocaleString()}}</strong></article></div><section class="quota-panel user-quota-panel"><div class="quota-heading"><div><p class="eyebrow">CURRENT PERIOD QUOTA</p><h3>剩余配额</h3></div><span>按用户组周期结算</span></div><div class="quota-list"><article v-for="row in usage.quotas" :key="row.userGroup"><div class="quota-group-name"><b>{{row.userGroup}}</b><span>{{row.period}}</span></div><div class="quota-dimensions"><div class="quota-dimension"><div class="quota-dimension-head"><span>个人配额</span><b>{{row.personalRemaining === null || row.personalRemaining === undefined ? '不限制' : `${row.personalRemaining.toLocaleString()} 剩余`}}</b></div><div class="quota-bar"><i :style="{width: row.personalQuota ? `${Math.min(100, row.personalUsed / row.personalQuota * 100)}%` : '0%'}"></i></div><small>{{row.personalQuota ? `${row.personalUsed.toLocaleString()} / ${row.personalQuota.toLocaleString()} Token` : '未设置个人额度'}}</small></div><div class="quota-dimension"><div class="quota-dimension-head"><span>组共享配额</span><b>{{row.groupRemaining === null || row.groupRemaining === undefined ? '不限制' : `${row.groupRemaining.toLocaleString()} 剩余`}}</b></div><div class="quota-bar"><i :style="{width: row.groupQuota ? `${Math.min(100, row.groupUsed / row.groupQuota * 100)}%` : '0%'}"></i></div><small>{{row.groupQuota ? `${row.groupUsed.toLocaleString()} / ${row.groupQuota.toLocaleString()} Token` : '未设置组额度'}}</small></div></div></article><p v-if="!usage.quotas.length" class="empty-note">当前未分配用户组配额。</p></div></section></section>
    </section>

    <el-drawer v-model="logDetailDrawer" title="调用详情" size="620px"><template v-if="selectedLog"><div class="log-request-id">Request ID: <code>{{detailValue(selectedLog.requestId)}}</code></div><section class="log-section"><h3>基本信息</h3><el-descriptions :column="1" border><el-descriptions-item label="用户">{{detailValue(selectedLog.userName)}}</el-descriptions-item><el-descriptions-item label="用户组">{{detailValue(selectedLog.userGroupNames)}}</el-descriptions-item><el-descriptions-item label="API Key">{{detailValue(selectedLog.apiKeyName)}}</el-descriptions-item><el-descriptions-item label="模型组">{{detailValue(selectedLog.modelGroupNames)}}</el-descriptions-item><el-descriptions-item label="调用时间">{{detailValue(selectedLog.createTime)}}</el-descriptions-item></el-descriptions></section><section class="log-section"><h3>模型详情</h3><el-descriptions :column="1" border><el-descriptions-item label="上游账号">{{detailValue(selectedLog.upstreamAccount)}}</el-descriptions-item><el-descriptions-item label="请求模型">{{detailValue(selectedLog.requestModel)}}</el-descriptions-item><el-descriptions-item label="上游模型">{{detailValue(selectedLog.upstreamModel)}}</el-descriptions-item><el-descriptions-item label="流式类型">{{selectedLog.stream ? '流式' : '非流式'}}</el-descriptions-item><el-descriptions-item label="上游端点">{{detailValue(selectedLog.upstreamEndpoint)}}</el-descriptions-item><el-descriptions-item label="协议路径">{{detailValue(selectedLog.protocolPath)}}</el-descriptions-item></el-descriptions></section><section class="log-section"><h3>Token 用量</h3><el-descriptions :column="2" border><el-descriptions-item label="总 Token">{{detailValue(selectedLog.totalTokens)}}</el-descriptions-item><el-descriptions-item label="输入">{{detailValue(selectedLog.inputTokens)}}</el-descriptions-item><el-descriptions-item label="输出">{{detailValue(selectedLog.outputTokens)}}</el-descriptions-item><el-descriptions-item label="缓存">{{detailValue(selectedLog.cacheTokens)}}</el-descriptions-item></el-descriptions></section><section class="log-section"><h3>状态</h3><el-descriptions :column="1" border><el-descriptions-item label="结果"><el-tag :type="selectedLog.statusCode<400?'success':'danger'">{{selectedLog.statusCode<400?'成功':'失败'}}</el-tag></el-descriptions-item><el-descriptions-item label="上游状态码">{{detailValue(selectedLog.upstreamStatusCode)}}</el-descriptions-item><el-descriptions-item label="总耗时">{{detailValue(selectedLog.latencyMs)}} ms</el-descriptions-item><el-descriptions-item label="首字耗时">{{detailValue(selectedLog.firstTokenMs)}} ms</el-descriptions-item><el-descriptions-item label="排队耗时">{{detailValue(selectedLog.queueMs)}} ms</el-descriptions-item><el-descriptions-item label="上游累计耗时">{{detailValue(selectedLog.upstreamLatencyMs)}} ms</el-descriptions-item><el-descriptions-item label="错误码">{{detailValue(selectedLog.errorCode)}}</el-descriptions-item><el-descriptions-item label="错误信息">{{detailValue(selectedLog.errorMsg)}}</el-descriptions-item></el-descriptions></section></template></el-drawer>
    <el-drawer v-model="userGroupDialog" :title="editingUserGroup?'编辑用户组':'新增用户组'" size="620px"><el-form label-position="top" class="user-group-form"><el-form-item label="名称"><el-input v-model="userGroupForm.name" maxlength="128" show-word-limit/></el-form-item><el-form-item label="组最大并发"><el-input-number v-model="userGroupForm.maxConcurrent" :min="0"/><small>0 表示不限制。</small></el-form-item><el-form-item label="单 API Key 最大并发"><el-input-number v-model="userGroupForm.apiKeyMaxConcurrent" :min="0"/><small>0 表示不限制。</small></el-form-item><el-form-item label="组最大 Token 配额"><el-input-number v-model="userGroupForm.tokenQuota" :min="0" :step="1000"/><small>0 表示不限制。</small></el-form-item><el-form-item label="Token 配额更新周期"><el-select v-model="userGroupForm.quotaPeriod"><el-option label="日" value="DAY"/><el-option label="周" value="WEEK"/><el-option label="月" value="MONTH"/><el-option label="年" value="YEAR"/></el-select></el-form-item><el-form-item label="组内成员最大 Token 配额"><el-input-number v-model="userGroupForm.memberTokenQuota" :min="0" :step="1000"/><small>0 表示不限制。</small></el-form-item><el-form-item label="组内成员最大并发"><el-input-number v-model="userGroupForm.memberMaxConcurrent" :min="0"/><small>0 表示不限制。</small></el-form-item><el-form-item label="组内成员" class="span-2"><el-select v-model="userGroupForm.memberIds" multiple filterable collapse-tags collapse-tags-tooltip placeholder="选择普通用户" style="width:100%"><el-option v-for="member in availableGroupMembers" :key="member.id" :label="member.name" :value="member.id"/></el-select><small>组级和成员级配额将作用于这些成员。</small></el-form-item><el-form-item label="授权模型组" class="span-2"><el-select v-model="userGroupForm.modelGroupIds" multiple filterable collapse-tags collapse-tags-tooltip placeholder="选择可调用的模型组" style="width:100%"><el-option v-for="group in availableAuthorizedModelGroups" :key="group.id" :label="group.name" :value="group.id"/></el-select><small>成员仅允许调用这些模型组内的模型。</small></el-form-item><el-form-item label="备注" class="span-2"><el-input v-model="userGroupForm.remark" type="textarea" :rows="3" maxlength="512" show-word-limit/></el-form-item></el-form><template #footer><el-button @click="userGroupDialog=false">取消</el-button><el-button type="primary" @click="saveUserGroup">保存</el-button></template></el-drawer>
    <el-drawer v-model="modelGroupDialog" :title="editingModelGroup?'编辑模型组':'新增模型组'" size="560px"><el-form label-position="top"><el-form-item label="名称"><el-input v-model="modelGroupForm.name" maxlength="128" show-word-limit /></el-form-item><el-form-item label="模型"><el-select v-model="modelGroupForm.models" multiple filterable collapse-tags collapse-tags-tooltip placeholder="从已有模型中选择" style="width:100%"><el-option v-for="model in availableGroupModels" :key="model" :label="model" :value="model" /></el-select><small class="form-note">仅显示当前网关已可路由的模型。</small></el-form-item><el-form-item label="备注"><el-input v-model="modelGroupForm.remark" type="textarea" :rows="3" maxlength="512" show-word-limit /></el-form-item></el-form><template #footer><el-button @click="modelGroupDialog=false">取消</el-button><el-button type="primary" @click="saveModelGroup">保存</el-button></template></el-drawer>
    <el-drawer v-model="channelDialog" :title="editingChannel?'编辑渠道':'新增渠道'" size="620px"><el-form label-position="top" class="channel-form"><el-form-item label="渠道名称"><el-input v-model="channelForm.name" /></el-form-item><el-form-item label="供应商"><el-input v-model="channelForm.provider" /></el-form-item><el-form-item label="Base URL"><el-input v-model="channelForm.baseUrl" placeholder="https://api.example.com" /></el-form-item><el-form-item label="API Key"><el-input v-model="channelForm.apiKey" type="password" show-password :placeholder="editingChannel?'留空则保留当前密钥':''" /></el-form-item><el-form-item label="主协议"><el-select v-model="channelForm.protocol" @change="changeChannelPrimaryProtocol"><el-option label="OpenAI Chat Completions" value="openai-completions"/><el-option label="OpenAI Responses" value="openai-responses"/><el-option label="Anthropic Messages" value="anthropic-messages"/></el-select></el-form-item><el-form-item label="支持协议"><el-checkbox-group v-model="channelForm.supportedProtocols" @change="ensureChannelProtocol"><el-checkbox value="openai-completions">OpenAI Chat Completions</el-checkbox><el-checkbox value="openai-responses">OpenAI Responses</el-checkbox><el-checkbox value="anthropic-messages">Anthropic Messages</el-checkbox></el-checkbox-group><small>主协议决定生产请求格式。</small></el-form-item><el-form-item label="优先级"><el-input-number v-model="channelForm.priority" :min="0" /></el-form-item><el-form-item label="权重"><el-input-number v-model="channelForm.weight" :min="1" /></el-form-item><el-form-item label="最大并发"><el-input-number v-model="channelForm.maxConcurrent" :min="0" /></el-form-item><el-form-item label="默认测试模型"><el-input v-model="channelForm.defaultTestModel" /></el-form-item><el-form-item label="状态"><el-switch v-model="channelForm.status" :active-value="1" :inactive-value="0" /></el-form-item><el-form-item label="备注"><el-input v-model="channelForm.remark" /></el-form-item></el-form><div class="binding-head"><h3>模型绑定</h3><div><el-button text type="primary" :loading="discoveringModels" @click="discoverUpstreamModels">获取上游模型</el-button><el-button text type="primary" :icon="Plus" @click="addChannelModel">手动添加</el-button></div></div><p class="binding-note">获取模型会请求当前 Base URL 的 <code>/v1/models</code>，勾选后追加到表单，保存渠道后才写入数据库。</p><div v-for="(model,index) in channelForm.models" :key="index" class="binding-row"><el-input v-model="model.modelName" placeholder="对外模型名"/><el-input v-model="model.upstreamModelName" placeholder="上游模型名"/><el-button text type="danger" @click="removeChannelModel(index)">移除</el-button></div><template #footer><el-button @click="channelDialog=false">取消</el-button><el-button type="primary" @click="saveChannel">保存并刷新路由</el-button></template></el-drawer>
    <el-dialog v-model="modelPickerDialog" title="从上游选择模型" width="640px" :close-on-click-modal="false"><p class="model-picker-hint">已发现 {{ discoveredModels.length }} 个模型。勾选后追加到当前渠道的模型绑定，保存渠道后才写入数据库。</p><el-checkbox-group v-model="selectedDiscoveredModels" class="model-picker-list"><el-checkbox v-for="model in discoveredModels" :key="model.id" :value="model.id" class="model-picker-item"><span>{{model.id}}</span><small v-if="model.ownedBy">{{model.ownedBy}}</small></el-checkbox></el-checkbox-group><template #footer><el-button @click="modelPickerDialog=false">取消</el-button><el-button type="primary" :disabled="!selectedDiscoveredModels.length" @click="appendSelectedModels">添加已勾选模型</el-button></template></el-dialog>
    <el-dialog v-model="testingDialog" :title="`测试渠道：${testingChannel?.name ?? ''}`" width="760px"><el-form label-position="top"><el-form-item label="测试提示词"><el-input v-model="testPrompt" maxlength="500" show-word-limit/></el-form-item><el-form-item label="选择模型"><div class="test-controls"><el-button text type="primary" @click="testModels=testingChannel?.models.map(model=>model.modelName) ?? []">全选</el-button><el-button text @click="testModels=[]">清空</el-button><small>单批最多 20 个，最多 4 个并发。</small></div><el-checkbox-group v-model="testModels" class="test-models"><el-checkbox v-for="model in testingChannel?.models ?? []" :key="model.id" :value="model.modelName">{{model.modelName}}</el-checkbox></el-checkbox-group></el-form-item></el-form><div v-if="testResults.length" class="test-results"><h3>测试结果</h3><el-table :data="testResults" class="dense-table" size="small"><el-table-column prop="modelName" label="模型" min-width="160"/><el-table-column label="状态" width="110"><template #default="{row}"><el-tag :type="row.success?'success':'danger'">{{row.success?'可用':'失败'}} {{row.statusCode ?? ''}}</el-tag></template></el-table-column><el-table-column prop="latencyMs" label="耗时(ms)" width="110"/><el-table-column label="回答 / 错误" min-width="260" show-overflow-tooltip><template #default="{row}">{{row.success?row.responsePreview:row.errorMessage}}</template></el-table-column></el-table></div><template #footer><el-button @click="testingDialog=false">关闭</el-button><el-button type="primary" :loading="testing" :disabled="!testModels.length" @click="runChannelTest">{{testModels.length>1?`批量测试 ${testModels.length} 个模型`:'测试模型'}}</el-button></template></el-dialog>
    <el-drawer v-model="userDialog" :title="editingUser?'编辑用户':'新增用户'" size="480px"><el-form label-position="top"><el-form-item label="用户名"><el-input v-model="userForm.username" :disabled="!!editingUser" /></el-form-item><el-form-item label="密码"><el-input v-model="userForm.password" type="password" show-password :placeholder="editingUser?'留空则不修改':''" /></el-form-item><el-form-item label="确认密码"><el-input v-model="userForm.confirmPassword" type="password" show-password /></el-form-item><el-form-item label="备注"><el-input v-model="userForm.remark" /></el-form-item><el-form-item label="状态"><el-switch v-model="userForm.status" :active-value="1" :inactive-value="0" active-text="启用" inactive-text="停用" /></el-form-item></el-form><template #footer><el-button @click="userDialog=false">取消</el-button><el-button type="primary" @click="saveUser">保存</el-button></template></el-drawer>
    <el-dialog v-model="keyDialog" title="创建 API Key" width="440px"><el-form label-position="top"><el-form-item label="备注"><el-input v-model="keyRemark" placeholder="例如：本地开发" /></el-form-item></el-form><template #footer><el-button @click="keyDialog=false">取消</el-button><el-button type="primary" @click="createKey">创建</el-button></template></el-dialog>
    <el-dialog v-model="keyRevealDialog" title="请立即保存 API Key" width="560px" :close-on-click-modal="false"><p class="token-warning">该明文仅显示一次。</p><div class="token-reveal"><code>{{revealedKey}}</code><el-button @click="copyKey">复制</el-button></div></el-dialog>
  </main>
</template>
